mapper.select:
SELECT fs.id, fsd.id AS detailId, fs.code, fs.shop_id AS shopId, fs.shop_name AS shopName, fs.country_id AS countryId, fs.country_name AS countryName, fs.fulfillment_center AS fulfillmentCenter, fs.delivery_status AS deliveryStatus, (SELECT fd.code FROM first_mile_delivery fd WHERE fd.source_id = fs.id AND fd.is_deleted = FALSE ORDER BY fd.create_time DESC LIMIT 1) AS deliveryCode, fs.platform_shipment_status AS platformShipmentStatus, fs.shipment_create_time AS shipmentCreateTime, fsd.receive_date AS shipmentReceiveTime, fsd.asin, fsd.msku, fsd.fn_sku AS fnSku, fsd.sku_no AS skuNo, fsd.declare_qty AS declareQty, fsd.diff_qty AS diffQty, fsd.is_combination AS isCombination FROM fba_shipment_detail fsd INNER JOIN fba_shipment fs ON fs.id = fsd.main_id AND fsd.is_deleted = FALSE WHERE fs.is_deleted = FALSE
AND fs.code ILIKE concat('%',#{params.code}::text,'%')
AND fsd.sku_no in
#{item}
AND fs.shop_id in
#{shopId}
AND fs.country_id in
#{countryId}
AND fs.fulfillment_center ILIKE concat('%',#{params.fulfillmentCenter}::text,'%')
AND fs.delivery_status in
#{deliveryStatus}
AND fs.platform_shipment_status in
#{platformShipmentStatus}
AND fsd.asin ILIKE concat('%',#{params.asin}::text,'%')
AND fsd.fn_sku ILIKE concat('%',#{params.fnSku}::text,'%')
AND fsd.msku ILIKE concat('%',#{params.msku}::text,'%')
and fsd.is_combination = #{params.isCombination}
AND fsd.diff_qty ${params.diffRule} 0
AND fs.shipment_create_time >= #{params.shipmentCreateTimeList[0]} AND (#{params.shipmentCreateTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > fs.shipment_create_time
AND fs.shipment_receive_time >= #{params.shipmentReceiveTimeList[0]} AND (#{params.shipmentReceiveTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > fs.shipment_receive_time
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
fs.create_time DESC

SELECT fsd.id, fsd.main_id, fs.code, fs.fulfillment_center, fs.shop_id, fs.shop_name, fs.country_id, fs.country_name, fsd.asin AS asin, fsd.msku AS msku, fsd.fn_sku, fsd.sku_no, fsd.declare_qty, fsd.is_combination FROM fba_shipment_detail fsd INNER JOIN fba_shipment fs ON fs.id = fsd.main_id AND fsd.is_deleted = FALSE WHERE fs.is_deleted = FALSE
and fs.id in
#{id}

SELECT fs.id AS sourceId, fsd.id AS sourceDetailId, fs.code AS sourceCode, fs.shop_id AS channelId, fs.shop_name AS channelName, fsd.asin, fsd.msku, fsd.fn_sku, fsd.sku_id, fsd.sku_no, fsd.declare_qty FROM fba_shipment_detail fsd INNER JOIN fba_shipment fs ON fs.id = fsd.main_id AND fsd.is_deleted = FALSE WHERE fs.is_deleted = FALSE
and fs.id in
#{id}
